    function respawnBoss(){ const d=RTD(); const t=dayType(); if(d&&bossRef){ bossRef.transaction(c=>{ if(c&&c.hp<=0&&Date.now()>(c.deadUntil||0)) return newBoss(c.id+1,t); return c; }); } else if(B.hp<=0){ B=newBoss(B.id+1,t); } }
