        // ═══════ Flaschenpost ═══════
    function addBottle(id,v){ if(!v||bottles[id]||!S) return; if(Date.now()-(v.t||0)>86400000) return; const a=(hash(id)%628)/100, r=60+(hash(id+'r')%190); const b={id,v,x:Math.cos(a)*r*.9,z:Math.sin(a)*r*.9}; const s=spr('🍾',4,b.x,2.2,b.z); b.s=s; bottles[id]=b; }
    function delBottle(id){ const b=bottles[id]; if(b){ S&&S.remove(b.s); delete bottles[id]; } }
    function tryBottles(){ Object.keys(bottles).forEach(id=>{ const b=bottles[id]; if(Math.hypot(b.x-st.x,b.z-st.z)<7){ if(b.v.from===me()) return; delete bottles[id]; S.remove(b.s); const done=(g,msg)=>{ addGold(g); showMsg('🍾 Flaschenpost von '+esc(b.v.from),esc(b.v.msg||'')+'<div style="margin-top:8px;color:#ffd54f;font-weight:900">+'+g+' 🪙</div>'); };
        const d=RTD(); if(d){ d.ref('zoo_pirate/bottles/'+id).transaction(c=>c?null:c,(err,ok,snap)=>{ if(ok) done(Math.round((b.v.gold||40)*goldMul()),b.v.msg); }); } else done(b.v.gold||40); } }); }
    P.sendBottle=function(msg){ const p=pir(), day=new Date().toISOString().slice(0,10); if(p.sent.day!==day) p.sent={day,n:0}; if(p.sent.n>=3) return toast('📅 Maximal 3 Flaschen pro Tag.'); msg=String(msg||'').trim().slice(0,60); if(msg.length<2) return toast('Schreib eine kurze Nachricht.'); if(p.gold<50) return toast('Du brauchst 50 🪙.');
      try{ if(window.ZRules&&ZRules.check){ const v=ZRules.check(msg); if(v&&v.block){ ZRules.report&&ZRules.report(v.rn,msg); return toast('🚫 Regel '+v.rn+': '+v.why,4000); } } }catch(e){}
      p.gold-=50; p.sent.n++; const o={from:me(),msg,gold:40,t:Date.now()}; const d=RTD(); if(d){ try{ d.ref('zoo_pirate/bottles').push(o); }catch(e){} } else addBottle('l'+Date.now(),o); hud(); save(true); toast('🍾 Flasche ins Meer geworfen!'); closeMenu(); };
    // ═══════ Monster ═══════
    function spawnSerp(){ const mx=evOn('frieden')?0:Math.max(0,Math.round(CFG.maxM))+(evOn('sturm')?2:0); if(serp.length>=mx||st.dead||st.isl) return; const a=Math.random()*6.283, r=55+Math.random()*40; const x=st.x+Math.cos(a)*r, z=st.z+Math.sin(a)*r; if(Math.hypot(x,z)>LIM-10||Object.values(ISL).some(I=>Math.hypot(x-I.x,z-I.z)<I.r+8)||Math.hypot(x,z)<50) return; const sh=Math.random()<.5, e=sh?'🦈':'🐍'; const m={x,z,hp:40,max:40,dmg:(sh?8:6),nm:sh?'einem Hai':'einer Seeschlange',s:spr(e,9,x,3,z),bar:spr('❤️',1,x,8,z),t:0,hh:''}; m.bar.visible=false; serp.push(m); heartsOf(m); }
    function heartsOf(m){ const n=Math.ceil(m.hp/10), t='❤️'.repeat(Math.max(0,n)); if(m.hh===t) return; m.hh=t; if(m.bar.parent) m.bar.parent.remove(m.bar); const l=lbl(t||' ','#fff',Math.max(4,m.max/10*2.6)); l.position.set(m.x,8,m.z); S.add(l); m.bar=l; }
    function killSerp(m,k){ S.remove(m.s); S.remove(m.bar); serp.splice(serp.indexOf(m),1); if(k){ vib('tap'); const p=pir(); p.kills=(p.kills||0)+1; const g=addGold((18+Math.random()*14)*goldMul()); toast('💥 Monster besiegt! +'+g+' 🪙',1800); if(Math.random()<.15) giveMap(); } }
    // ═══════ Schiessen ═══════
    function fire(){ if(st.dead||st.fireCd>0) return; let tg=null,td=70; serp.forEach(m=>{ const d=Math.hypot(m.x-st.x,m.z-st.z); if(d<td){ td=d; tg={t:'s',m,x:m.x,z:m.z}; } }); if(B.hp>0){ const bp=bossPos(); const d=Math.hypot(bp.x-st.x,bp.z-st.z); if(d<95&&d-12<td){ td=d; tg={t:'b',x:bp.x,z:bp.z}; } }
      if(!tg) return toast('🎯 Kein Ziel in Reichweite.',1200); st.fireCd=.8; vib('boom'); const b=ball(.9,0x212121,st.x,3,st.z); balls.push({m:b,sx:st.x,sz:st.z,tx:tg.x,tz:tg.z,t:0,tg,dur:Math.max(.2,td/110)}); }
    const bossPos=()=>{ const t=Date.now()/4000; return {x:BOSSC.x+Math.cos(t)*28,z:BOSSC.z+Math.sin(t)*20}; };
    function hurt(d,by){ if(st.dead) return; st.hp-=d; st.last=by||'einem Monster'; hud(); flash(d);
      if(st.hp<=0){ st.hp=0; st.dead=1; st.v=0; vib('death'); const p=pir(); const lose=Math.round(p.gold*.1); p.gold-=lose; const bp0=bossPos(), healed=B.hp>0&&B.hp<B.max&&((p.bd.id===B.id&&p.bd.dmg>0)||Math.hypot(bp0.x-st.x,bp0.z-st.z)<140); if(healed) healBoss(); st.healed=healed?BT[B.type].ic+' '+BT[B.type].n:''; save(true); hud(); try{ ZP.toast('☠️ Dein Schiff ist gesunken!',3000); }catch(e){}
        setTimeout(()=>{ if(!st.dead||!P.open) return; const o=document.createElement('div'); o.id='zpi-death'; o.style.cssText='position:absolute;inset:0;z-index:5;background:rgba(110,10,10,.65);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;color:#fff;text-align:center;padding:16px'; const bt='width:min(340px,80vw);padding:12px 10px;background:#7a7a7a;border:2px solid #1a1a1a;border-bottom-color:#3a3a3a;color:#fff;font-size:1.1rem;font-weight:700;cursor:pointer;box-shadow:inset 0 -3px 0 rgba(0,0,0,.35)'; o.innerHTML='<div style="font-size:clamp(2.2rem,8vw,3.6rem);font-weight:900;text-shadow:3px 3px 0 #333">☠️ Game over!</div><div style="font-size:1.05rem;max-width:90vw">'+esc(me())+' wurde von '+esc(st.last)+' versenkt.</div><div style="font-size:.9rem;opacity:.9">−'+lose+' 🪙 (10 % deines Goldes)</div>'+(st.healed?'<div style=\"font-size:.9rem;color:#ffcc80\">⚠️ '+esc(st.healed)+' hat sich vollständig geheilt!</div>':'')+'<button id=\"zpi-resp\" style="'+bt+'">⚓ Zurück im Hafen</button><button id="zpi-tozoo" style="'+bt+'">🦁 Zum Zoo</button>'; ov.appendChild(o); $('zpi-resp').onclick=respawn; $('zpi-tozoo').onclick=()=>{ respawn(); P.close(); }; },1600); } }
