       +'<div style="'+sec+'"><b>6 · Monster</b> (max. gleichzeitig / Schaden ×)<input id="za-mm" type="number" value="'+CFG.maxM+'" style="'+inp+'"><input id="za-md" type="number" step=".1" value="'+CFG.mdmg+'" style="'+inp+'"><button id="za-mb" style="'+bt+'">Speichern</button></div>'
