      $('za-kill').onclick=()=>{ const r=aref('boss'); const nb=Object.assign({},B,{hp:0,deadUntil:Date.now()+600000}); if(r) r.set(nb); else setBoss(nb); toast('☠️ Boss getötet'); };
      $('za-heal').onclick=()=>{ const r=aref('boss'); const nb=Object.assign({},B,{hp:B.max,deadUntil:0}); if(r) r.set(nb); else B=nb; toast('💚 Boss geheilt'); };
      $('za-hpb').onclick=()=>{ const v=Math.max(50,+$('za-hp').value||2500); const nb=Object.assign({},B,{hp:v,max:v}); const r=aref('boss'); if(r) r.set(nb); else B=nb; toast('✅ Boss-Leben '+v); };
